// Logo SVG del SATSAID (basado en su identidad: letras SATSAID en azul)
const LOGO_SRC = "data:image/png;base64,";
const SATSAID_LOGO = ({ width = 180 }) => (
  <img src={LOGO_SRC} alt="SATSAID" style={{ width: width, maxWidth: "100%", objectFit: "contain" }} />
);


// ── SONIDO (Web Audio API, sin archivos externos) ─────────────────────────────
function playWinSound(rarity = "common") {
  try {
    const ctx = new (window.AudioContext || window.webkitAudioContext)();
    const configs = {
      legendary: [[523,0.0,0.08],[659,0.09,0.08],[784,0.18,0.08],[1047,0.27,0.25],[1319,0.40,0.4]],
      epic:      [[523,0.0,0.08],[659,0.09,0.08],[784,0.18,0.08],[1047,0.27,0.35]],
      rare:      [[440,0.0,0.08],[554,0.09,0.08],[659,0.18,0.25]],
      common:    [[440,0.0,0.08],[523,0.09,0.18]],
    };
    (configs[rarity] || configs.common).forEach(([freq, start, dur]) => {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.connect(gain); gain.connect(ctx.destination);
      osc.frequency.value = freq;
      osc.type = "sine";
      gain.gain.setValueAtTime(0, ctx.currentTime + start);
      gain.gain.linearRampToValueAtTime(0.18, ctx.currentTime + start + 0.02);
      gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + start + dur);
      osc.start(ctx.currentTime + start);
      osc.stop(ctx.currentTime + start + dur + 0.05);
    });
  } catch(e) {}
}

