function ProgressBar({ value, max, color }) {
  return (
    <div style={{ width: "100%", borderRadius: 99, height: 10, background: "#E0E0E0", overflow: "hidden" }}>
      <div style={{ width: `${Math.min(100, (value / max) * 100)}%`, height: "100%", background: color, borderRadius: 99, transition: "width .7s" }} />
    </div>
  );
}

function Toast({ msg, onDone }) {
  useEffect(() => { const t = setTimeout(onDone, 3000); return () => clearTimeout(t); }, []);
  return (
    <div style={{
      position: "fixed", top: 24, left: "50%", transform: "translateX(-50%)", zIndex: 100,
      padding: "12px 24px", borderRadius: 20, color: "white", fontWeight: 800, fontSize: 14,
      boxShadow: "0 8px 32px #0004", background: "linear-gradient(135deg,#1a237e,#283593)",
      maxWidth: "88vw", textAlign: "center",
    }}>{msg}</div>
  );
}

// ── MODAL NUEVA FIGURITA ──────────────────────────────────────────────────────
function NewStickerModal({ sticker, onClose }) {
  const rc = RARITY_CONFIG[sticker.rarity];
  const [phase, setPhase] = useState("flip"); // flip -> shine -> show

  useEffect(() => {
    playWinSound(sticker.rarity);
    const t1 = setTimeout(() => setPhase("shine"), 350);
    const t2 = setTimeout(() => setPhase("show"), 750);
    return () => { clearTimeout(t1); clearTimeout(t2); };
  }, []);

  const glowColors = {
    legendary: "#F9A825", epic: "#7B1FA2", rare: "#1976D2", common: "#78909C"
  };

  return (
    <div onClick={phase === "show" ? onClose : null} style={{
      position: "fixed", inset: 0, zIndex: 50,
      display: "flex", alignItems: "center", justifyContent: "center",
      background: "rgba(0,0,0,0.75)", padding: 16,
    }}>
      <style>{`
        @keyframes cardFlip {
          0%   { transform: rotateY(90deg) scale(0.6); opacity: 0; }
          60%  { transform: rotateY(-8deg) scale(1.08); opacity: 1; }
          100% { transform: rotateY(0deg) scale(1); opacity: 1; }
        }
        @keyframes shine {
          0%   { opacity: 0; transform: scale(0.8); }
          50%  { opacity: 1; transform: scale(1.15); }
          100% { opacity: 0; transform: scale(1.4); }
        }
        @keyframes particles {
          0%   { transform: translateY(0) scale(1); opacity: 1; }
          100% { transform: translateY(-60px) scale(0); opacity: 0; }
        }
        @keyframes badgePop {
          0%   { transform: scale(0); }
          70%  { transform: scale(1.3); }
          100% { transform: scale(1); }
        }
      `}</style>

      <div onClick={e => e.stopPropagation()} style={{
        background: "white", borderRadius: 28, padding: "32px 24px 24px",
        textAlign: "center", maxWidth: 300, width: "100%",
        boxShadow: `0 0 60px ${glowColors[sticker.rarity]}66, 0 24px 64px #0008`,
        animation: "cardFlip 0.75s cubic-bezier(.17,.67,.35,1.2) both",
        position: "relative", overflow: "hidden",
      }}>
        {/* Shine burst */}
        {phase === "shine" && (
          <div style={{
            position: "absolute", inset: 0, borderRadius: 28,
            background: `radial-gradient(circle, ${glowColors[sticker.rarity]}44 0%, transparent 70%)`,
            animation: "shine 0.5s ease-out both", pointerEvents: "none",
          }} />
        )}
        {/* Particles */}
        {phase !== "flip" && sticker.rarity !== "common" && (
          <div style={{ position: "absolute", top: 0, left: 0, right: 0, pointerEvents: "none" }}>
            {["⭐","✨","🌟","💫"].map((e, i) => (
              <span key={i} style={{
                position: "absolute", left: `${20 + i * 20}%`, top: 20, fontSize: 18,
                animation: `particles ${0.6 + i * 0.15}s ease-out ${i * 0.1}s both`,
              }}>{e}</span>
            ))}
          </div>
        )}

        {/* Rarity badge top */}
        <div style={{
          display: "inline-block", padding: "3px 14px", borderRadius: 20,
          background: rc.color, color: "white", fontWeight: 900, fontSize: 11,
          marginBottom: 16, animation: phase === "show" ? "badgePop 0.4s ease-out both" : "none",
        }}>{rc.label.toUpperCase()}</div>

        <div style={{ display: "flex", justifyContent: "center", marginBottom: 16, position: "relative" }}>
          <div style={{
            borderRadius: "50%",
            boxShadow: phase !== "flip" ? `0 0 32px 8px ${glowColors[sticker.rarity]}88` : "none",
            transition: "box-shadow 0.4s",
          }}>
            <Avatar sticker={sticker} size={100} owned={true} />
          </div>
        </div>

        <div style={{ fontWeight: 900, fontSize: 19, color: "#1a1a3e", marginBottom: 2 }}>{sticker.name}</div>
        <div style={{ fontSize: 12, color: "#888", marginBottom: 12 }}>{sticker.role}</div>

        <div style={{ background: rc.bg, borderRadius: 12, padding: "9px 12px", marginBottom: 18, fontSize: 11, color: "#555", lineHeight: 1.5 }}>
          {sticker.desc}
        </div>

        <button onClick={onClose} style={{
          width: "100%", padding: 13, borderRadius: 14, border: "none", cursor: "pointer",
          background: `linear-gradient(135deg,${rc.color},${glowColors[sticker.rarity]})`,
          color: "white", fontWeight: 900, fontSize: 15,
        }}>¡Genial! 🌟</button>
      </div>
    </div>
  );
}

